package com.misclickers.bingo;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("bingo")
public interface BingoConfig extends Config {
    @ConfigItem(
            keyName = "baseUrl",
            name = "Backend URL",
            description = "Base URL of the bingo backend",
            position = 0
    )
    default String baseUrl() {
        return "https://bingo-backend-production-d903.up.railway.app";
    }

    @ConfigItem(
            keyName = "joinCode",
            name = "Team join code",
            description = "The code your bingo organizer gave your team",
            position = 1
    )
    default String joinCode() {
        return "";
    }

    @ConfigItem(
            keyName = "showProgressOverlay",
            name = "Show progress overlay",
            description = "Show the on-screen overlay listing tiles your team has partial progress on",
            position = 2
    )
    default boolean showProgressOverlay() {
        return true;
    }
}

package com.misclickers.bingo;

import com.misclickers.bingo.api.dto.BoardStateResponse;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.FlowLayout;

public class BingoPanel extends PluginPanel {
    private final JLabel teamLabel = new JLabel(" ");
    private final JLabel statusLabel = new JLabel("Not connected");
    private final JLabel scoreLabel = new JLabel(" ");
    private final JPanel gridPanel = new JPanel();
    // gridPanel sits inside this FlowLayout wrapper rather than being added
    // to the outer BorderLayout directly. FlowLayout is what stops the grid
    // from being stretched to fill the sidebar's full height — it always
    // respects its child's own preferred size instead of expanding it,
    // which is what let the tiles get stretched into tall rectangles before.
    private final JPanel gridWrapper = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));

    private final ItemManager itemManager;
    private Runnable onRefresh;

    public BingoPanel(ItemManager itemManager) {
        super(false);
        this.itemManager = itemManager;
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        // Header styled as its own card (DARKER_GRAY_COLOR fill, padding,
        // thin divider underneath) rather than sitting flush against the
        // sidebar background — same pattern the Wise Old Man plugin uses to
        // separate its header/search area from the rest of the panel.
        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        header.setBorder(new CompoundBorder(
                new MatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
                new EmptyBorder(10, 10, 10, 10)));

        teamLabel.setForeground(Color.WHITE);
        teamLabel.setFont(FontManager.getRunescapeBoldFont());
        statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        statusLabel.setFont(FontManager.getRunescapeSmallFont());
        scoreLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        scoreLabel.setFont(FontManager.getRunescapeSmallFont());

        JButton refreshButton = new JButton("Refresh");
        refreshButton.setAlignmentX(Component.LEFT_ALIGNMENT);
        refreshButton.addActionListener(e -> {
            if (onRefresh != null) {
                onRefresh.run();
            }
        });

        teamLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        scoreLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

        header.add(teamLabel);
        header.add(Box.createVerticalStrut(4));
        header.add(statusLabel);
        header.add(scoreLabel);
        header.add(Box.createVerticalStrut(6));
        header.add(refreshButton);
        add(header, BorderLayout.NORTH);

        gridPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        gridWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
        gridWrapper.add(gridPanel);
        add(gridWrapper, BorderLayout.CENTER);
    }

    public void setOnRefresh(Runnable onRefresh) {
        this.onRefresh = onRefresh;
    }

    /** Set once after a successful join — see BingoPlugin.attemptJoin(). */
    public void setTeamName(String teamName) {
        teamLabel.setText("Team: " + teamName);
    }

    public void showConnecting() {
        statusLabel.setText("Connecting...");
    }

    public void showError(String message) {
        statusLabel.setText("Error: " + message);
    }

    public void render(BoardStateResponse state) {
        statusLabel.setText(state.board.name);
        scoreLabel.setText("Score: " + state.score.total
                + " (" + state.score.completedCount + "/" + state.tiles.size() + " tiles)");

        // Grid cell construction (icons, progress labels, rounded tiles,
        // square-cell sizing) lives in BoardGridRenderer now — shared with
        // LeaderboardPanel's read-only spectate view.
        BoardGridRenderer.render(gridPanel, state, itemManager, PANEL_WIDTH);

        gridWrapper.revalidate();
        gridWrapper.repaint();
        revalidate();
        repaint();
    }
}

package com.misclickers.bingo;

import com.google.inject.Provides;
import com.misclickers.bingo.ChatEventDetector.DetectedEvent;
import com.misclickers.bingo.api.BingoApiClient;
import com.misclickers.bingo.api.UnauthorizedException;
import com.misclickers.bingo.api.dto.BoardStateResponse;
import com.misclickers.bingo.api.dto.CompletionResponse;
import com.misclickers.bingo.api.dto.JoinResponse;
import com.misclickers.bingo.api.dto.TeamsListResponse;
import com.misclickers.bingo.api.dto.TileState;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ExecutorServiceExceptionLogger;
import net.runelite.client.util.Text;

import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.swing.JTabbedPane;
import javax.swing.SwingUtilities;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.regex.Matcher;

@Slf4j
@PluginDescriptor(
        name = "Misclickers Clan Bingo",
        description = "Coordinate clan bingo boards with automatic team sync",
        tags = {"bingo", "pvm", "minigame", "clan"}
)
public class BingoPlugin extends Plugin {
    @Inject
    private Client client;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private BingoConfig config;

    @Inject
    private BingoApiClient apiClient;

    @Inject
    private ItemManager itemManager;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private TileCompletionOverlay completionOverlay;

    @Inject
    private BingoProgressOverlay progressOverlay;

    @Inject
    private AudioPlayer audioPlayer;

    // How often teammates' progress gets pulled in the background. This
    // replaced a Socket.IO push connection (see git history) after a Plugin
    // Hub maintainer rejected socket.io-client as a new third-party
    // dependency on PR #13948 — polling trades a little latency for using
    // only RuneLite's own already-bundled HTTP client, no new dependency at
    // all. The player who actually detects an event still sees it instantly
    // via the direct refreshBoard() call in reportCompletion(); this is only
    // for picking up teammates' completions.
    private static final int POLL_INTERVAL_SECONDS = 20;

    // Own executor rather than a Guice-provided one, following the same
    // pattern as RuneLite's own WorldHopperPlugin — created in startUp(),
    // torn down in shutDown().
    private ScheduledExecutorService pollExecutor;
    private ScheduledFuture<?> pollFuture;

    // Classpath-resource path to the tile-completion sound, bundled at
    // src/main/resources/tile_complete.wav. This is a synthesized placeholder
    // chime, not the real "Task Mastered (Leagues)" jingle — that's Jagex's
    // copyrighted game audio, so it isn't something to source and bundle
    // here. To use the real jingle instead, personally export the clip from
    // your own client and replace that file at the same path; nothing else
    // needs to change.
    private static final String COMPLETION_SOUND_RESOURCE = "/tile_complete.wav";

    private BingoPanel panel;
    private LeaderboardPanel leaderboardPanel;
    private NavigationButton navButton;
    private String boardId;
    private boolean joined;

    // Team id currently selected in the leaderboard dropdown. Null until
    // the teams list has loaded and a selection has been made (setTeams()
    // auto-selects the first entry, which drives the first fetch).
    private volatile String selectedLeaderboardTeamId;

    // The join code actually used for the current `joined` session, captured
    // at attemptJoin() time. Compared against config.joinCode() so a code
    // typed into settings after joining is detected as "this needs a fresh
    // join", instead of `joined` staying true and every Refresh/poll just
    // re-fetching the old team's state forever. Cleared alongside
    // joined/boardId in shutDown().
    private String joinedCode;

    // Last board state fetched from the server — this is what chat-detected
    // events get matched against locally before reporting. Kept up to date
    // by refreshBoard(), called both on each detected event and on the
    // POLL_INTERVAL_SECONDS background poll; it can go briefly stale between
    // those, which just means a just-completed tile might get one redundant
    // (harmless) completion report before the next fetch.
    private volatile BoardStateResponse currentState;

    // Set when a "You have opened Larran's chest" chat message is seen;
    // holds an item-id -> quantity snapshot of the inventory taken at that
    // instant, so the next inventory-changed event can be diffed against it
    // to work out what the chest actually gave. Cleared after that one diff,
    // win or lose — chests don't fire NpcLootReceived, so this is the only
    // way to detect their contents. Only ever touched from the client
    // thread (chat + inventory events are both delivered there), so no
    // extra synchronization is needed.
    private Map<Integer, Integer> pendingChestSnapshot;

    @Provides
    BingoConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(BingoConfig.class);
    }

    @Override
    protected void startUp() {
        panel = new BingoPanel(itemManager);
        panel.setOnRefresh(() -> new Thread(this::connectOrRefresh, "bingo-refresh").start());

        leaderboardPanel = new LeaderboardPanel(itemManager);
        leaderboardPanel.setOnTeamSelected(teamId -> {
            selectedLeaderboardTeamId = teamId;
            new Thread(() -> refreshLeaderboardTeam(teamId), "bingo-leaderboard-select").start();
        });

        // BingoPanel itself is a PluginPanel (required by NavigationButton),
        // so the tab container has to be a separate, plain PluginPanel that
        // just hosts a JTabbedPane wrapping both views.
        // PluginPanel is abstract — this anonymous subclass has nothing to
        // override, it just exists to satisfy that and give the
        // JTabbedPane something concrete to live inside.
        PluginPanel container = new PluginPanel(false) {};
        container.setLayout(new BorderLayout());
        JTabbedPane tabs = new JTabbedPane();
        tabs.addTab("My Board", panel);
        tabs.addTab("Leaderboard", leaderboardPanel);
        // Loads the teams list (and, once selected, that team's state) the
        // first time the player actually opens the tab, rather than on every
        // startUp()/poll regardless of whether they ever look at it.
        tabs.addChangeListener(e -> {
            if (tabs.getSelectedComponent() == leaderboardPanel && joined) {
                new Thread(this::refreshLeaderboardTeams, "bingo-leaderboard-teams").start();
            }
        });
        container.add(tabs, BorderLayout.CENTER);

        navButton = NavigationButton.builder()
                .tooltip("Misclickers Clan Bingo")
                .icon(createBingoIcon())
                .priority(5)
                .panel(container)
                .build();
        clientToolbar.addNavigation(navButton);
        overlayManager.add(completionOverlay);
        overlayManager.add(progressOverlay);

        pollExecutor = new ExecutorServiceExceptionLogger(Executors.newSingleThreadScheduledExecutor());
        pollFuture = pollExecutor.scheduleWithFixedDelay(() -> {
            if (joined) {
                refreshBoard();
                // Keeps whichever team is currently selected in the
                // leaderboard dropdown up to date too, same cadence as the
                // player's own board — the dropdown itself only (re)loads
                // when the player opens the tab (see the JTabbedPane
                // ChangeListener in startUp()).
                String selectedTeamId = selectedLeaderboardTeamId;
                if (selectedTeamId != null) {
                    refreshLeaderboardTeam(selectedTeamId);
                }
            }
        }, POLL_INTERVAL_SECONDS, POLL_INTERVAL_SECONDS, TimeUnit.SECONDS);

        joined = false;
    }

    @Override
    protected void shutDown() {
        clientToolbar.removeNavigation(navButton);
        overlayManager.remove(completionOverlay);
        overlayManager.remove(progressOverlay);

        if (pollFuture != null) {
            pollFuture.cancel(true);
            pollFuture = null;
        }
        if (pollExecutor != null) {
            pollExecutor.shutdown();
            pollExecutor = null;
        }

        joined = false;
        boardId = null;
        joinedCode = null;
        selectedLeaderboardTeamId = null;
    }

    /** Read by BingoProgressOverlay to render live per-tile progress. */
    public BoardStateResponse getCurrentState() {
        return currentState;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        // Previously skipped entirely whenever already `joined` with an
        // unchanged join code — intended to avoid a pointless re-join, but
        // it also meant a relog or world-hop that doesn't restart RuneLite
        // itself (so `joined` is still true from before) never reloaded the
        // board on login; the player had to hit Refresh manually every
        // time. connectOrRefresh() already short-circuits to a plain
        // refreshBoard() (not a full re-join) when nothing's actually
        // changed, so always calling it here is cheap.
        if (event.getGameState() != GameState.LOGGED_IN) {
            return;
        }
        new Thread(this::connectOrRefresh, "bingo-join").start();
    }

    /**
     * Re-joins as soon as the join code setting changes, rather than waiting
     * for the player to notice nothing updated and hit Refresh. Guarded by
     * joinCodeChanged() itself (via connectOrRefresh) so edits to the other
     * config items don't trigger a pointless network call.
     */
    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!"bingo".equals(event.getGroup()) || !"joinCode".equals(event.getKey())) {
            return;
        }
        new Thread(this::connectOrRefresh, "bingo-rejoin").start();
    }

    /**
     * True once a join has succeeded but the join code in settings no longer
     * matches the one that join used — i.e. the player changed it and we
     * haven't caught up yet.
     */
    private boolean joinCodeChanged() {
        String current = config.joinCode() == null ? "" : config.joinCode().trim();
        String joinedAs = joinedCode == null ? "" : joinedCode;
        return !current.equals(joinedAs);
    }

    /**
     * Shared entry point for both the login trigger and the panel's Refresh
     * button: (re)joins if we haven't yet or the join code has since changed
     * (e.g. it was set/edited after login, so the login trigger fired too
     * early, or too late, to see the current value), otherwise just
     * re-fetches current board state. Runs blocking network calls — always
     * called from a background thread, never the client thread.
     */
    private void connectOrRefresh() {
        if (!joined || joinCodeChanged()) {
            attemptJoin();
        } else {
            refreshBoard();
        }
    }

    private void attemptJoin() {
        if (config.joinCode() == null || config.joinCode().isEmpty()) {
            SwingUtilities.invokeLater(() -> panel.showError("Set a join code in the plugin's settings first"));
            return;
        }
        String rsn = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
        if (rsn == null) {
            SwingUtilities.invokeLater(() -> panel.showError("Not logged in yet"));
            return;
        }

        SwingUtilities.invokeLater(panel::showConnecting);
        apiClient.setBaseUrl(config.baseUrl()); // re-read in case it changed since startUp()

        try {
            JoinResponse joinResponse = apiClient.join(config.joinCode(), rsn);
            this.boardId = joinResponse.boardId;
            this.joined = true;
            this.joinedCode = config.joinCode().trim();
            SwingUtilities.invokeLater(() -> panel.setTeamName(joinResponse.teamName));
            refreshBoard(false);
        } catch (Exception e) {
            SwingUtilities.invokeLater(() -> panel.showError(e.getMessage()));
            this.joined = false;
            this.joinedCode = null;
        }
    }

    private void refreshBoard() {
        refreshBoard(true);
    }

    /**
     * allowRejoinOnUnauthorized is false only for the refresh attemptJoin()
     * itself makes right after getting a brand new token — otherwise a
     * server that somehow keeps rejecting even freshly issued tokens would
     * send attemptJoin() and refreshBoard() into unbounded mutual recursion
     * on the same thread until it stack-overflows, which (for the poll
     * loop's thread) would silently kill all future polling, i.e. exactly
     * the "has to restart the plugin" failure this is meant to fix, just
     * better hidden. One rejoin attempt per real failure is enough.
     */
    private void refreshBoard(boolean allowRejoinOnUnauthorized) {
        if (boardId == null) {
            return;
        }
        try {
            BoardStateResponse state = apiClient.fetchBoardState(boardId);
            this.currentState = state;
            SwingUtilities.invokeLater(() -> panel.render(state));
        } catch (UnauthorizedException e) {
            if (allowRejoinOnUnauthorized) {
                // Token's missing/expired — re-join to get a fresh one
                // instead of just sitting on the error until the player
                // notices and restarts the plugin themselves.
                joined = false;
                attemptJoin();
            } else {
                SwingUtilities.invokeLater(() -> panel.showError("Session expired and rejoin failed — check your join code in settings"));
            }
        } catch (Exception e) {
            SwingUtilities.invokeLater(() -> panel.showError(e.getMessage()));
        }
    }

    /** Fetches the board's team list and populates the leaderboard dropdown. */
    private void refreshLeaderboardTeams() {
        if (boardId == null) {
            return;
        }
        try {
            TeamsListResponse response = apiClient.fetchTeams(boardId);
            SwingUtilities.invokeLater(() -> leaderboardPanel.setTeams(response.teams));
        } catch (Exception e) {
            SwingUtilities.invokeLater(() -> leaderboardPanel.showError(e.getMessage()));
        }
    }

    /** Fetches and renders one other team's board state for the leaderboard tab. */
    private void refreshLeaderboardTeam(String teamId) {
        if (boardId == null) {
            return;
        }
        try {
            BoardStateResponse state = apiClient.fetchTeamState(boardId, teamId);
            SwingUtilities.invokeLater(() -> leaderboardPanel.render(state));
        } catch (Exception e) {
            SwingUtilities.invokeLater(() -> leaderboardPanel.showError(e.getMessage()));
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        // Matches RuneLite's own ChatCommandsPlugin.onChatMessage() type
        // filter exactly (TRADE/GAMEMESSAGE/SPAM/FRIENDSCHATNOTIFICATION).
        // Previously this only allowed GAMEMESSAGE/SPAM, which silently
        // dropped raid-completion messages — RuneLite's RaidsPlugin sends
        // "Congratulations - your raid is complete!" as
        // FRIENDSCHATNOTIFICATION specifically, and boss/activity kill-count
        // messages (e.g. "Your completed Chambers of Xeric: Challenge Mode
        // count is: N") can arrive that way too. Without this, RAID_COMPLETE
        // and any raid-related KILL_COUNT match never reached
        // ChatEventDetector.detect() at all.
        // Also allow CLAN_MESSAGE/CLAN_GUEST_MESSAGE — the modern clan drop
        // broadcast ("<name> received a drop: <item>") is a clan *system*
        // message, not GAMEMESSAGE/SPAM/FRIENDSCHATNOTIFICATION, and it's
        // currently the only way to detect minigame/Thieving/skilling drops
        // that never pass through an NPC kill (e.g. Pharaoh's sceptre).
        if (event.getType() != ChatMessageType.TRADE
                && event.getType() != ChatMessageType.GAMEMESSAGE
                && event.getType() != ChatMessageType.SPAM
                && event.getType() != ChatMessageType.FRIENDSCHATNOTIFICATION
                && event.getType() != ChatMessageType.CLAN_MESSAGE
                && event.getType() != ChatMessageType.CLAN_GUEST_MESSAGE) {
            return;
        }

        // Larran's chest doesn't tell us what it gave in the message itself
        // — snapshot inventory now so the next onItemContainerChanged can
        // diff against it. Handled separately from ChatEventDetector.detect()
        // below since it needs Client/inventory access that pure function
        // deliberately doesn't have.
        Matcher larranChest = ChatPatterns.LARRAN_CHEST_OPENED.matcher(event.getMessage());
        if (larranChest.find()) {
            pendingChestSnapshot = snapshotInventory();
        }

        // Clan drop broadcasts are visible to every clan member, not just
        // whoever got the drop — without this check, every online teammate's
        // client would independently report the same single drop, inflating
        // team progress by however many teammates happened to be logged in.
        // Only dispatch when the broadcast is actually about the local player.
        Matcher dropBroadcast = ChatPatterns.CLAN_DROP_BROADCAST.matcher(event.getMessage());
        if (dropBroadcast.find()) {
            String reportedName = dropBroadcast.group(1).trim().replace(' ', ' ');
            String itemName = dropBroadcast.group(2).trim();
            Player localPlayer = client.getLocalPlayer();
            String localName = localPlayer == null ? null : localPlayer.getName();
            if (localName != null && localName.trim().replace(' ', ' ').equalsIgnoreCase(reportedName)) {
                dispatch(new DetectedEvent("ITEM_OBTAINED", itemName, 1, event.getMessage()));
            }
            return;
        }

        DetectedEvent detected = ChatEventDetector.detect(event.getMessage());
        if (detected != null) {
            dispatch(detected);
        }
    }

    private Map<Integer, Integer> snapshotInventory() {
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null) {
            return new HashMap<>();
        }
        return aggregateItems(inventory.getItems());
    }

    private static Map<Integer, Integer> aggregateItems(Item[] items) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (Item item : items) {
            if (item.getId() <= 0) {
                continue;
            }
            counts.merge(item.getId(), item.getQuantity(), Integer::sum);
        }
        return counts;
    }

    // Fires whenever any item container changes — filtered down to the
    // player's inventory, and only acted on if a Larran's chest open was
    // just seen in chat (pendingChestSnapshot != null). Diffs current
    // inventory against that snapshot to find what the chest gave, since
    // chests have no dedicated loot event the way NPC kills do.
    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        Map<Integer, Integer> snapshot = pendingChestSnapshot;
        if (snapshot == null || event.getContainerId() != InventoryID.INV) {
            return;
        }
        pendingChestSnapshot = null; // one-shot: only diff against the very next change

        Map<Integer, Integer> current = aggregateItems(event.getItemContainer().getItems());
        for (Map.Entry<Integer, Integer> entry : current.entrySet()) {
            int gained = entry.getValue() - snapshot.getOrDefault(entry.getKey(), 0);
            if (gained <= 0) {
                continue;
            }
            ItemComposition composition = itemManager.getItemComposition(entry.getKey());
            String rawEvidence = "Larran's chest gave " + gained + "x " + composition.getName();
            dispatch(new DetectedEvent("ITEM_OBTAINED", composition.getName(), gained, rawEvidence));
        }
    }

    // Item drops are tracked here rather than via chat, since this fires on
    // every kill with the real quantity obtained — the collection log chat
    // message only ever fires once, the very first time you get a given
    // item, which can't track tiles that need more than one (e.g. "obtain 3
    // Sarachnis cudgels"). See ChatPatterns.COLLECTION_LOG_ITEM for the full
    // reasoning. Larran's chest (a non-NPC-kill source) is handled separately
    // via inventory diffing — see onChatMessage/onItemContainerChanged.
    // Other chest/minigame reward sources aren't covered yet — known gap.
    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event) {
        for (ItemStack itemStack : event.getItems()) {
            ItemComposition composition = itemManager.getItemComposition(itemStack.getId());
            String rawEvidence = event.getNpc().getName() + " dropped " + itemStack.getQuantity() + "x " + composition.getName();
            dispatch(new DetectedEvent("ITEM_OBTAINED", composition.getName(), itemStack.getQuantity(), rawEvidence));
        }
    }

    // General-purpose "you killed an NPC" signal, sourced from the game's
    // own native loot-tracking system — the same data that powers RuneLite's
    // built-in Loot Tracker panel and the in-game "View loot" summary. Unlike
    // NpcLootReceived (ground-item based; only fires when there's something
    // to pick up off the ground) or the "Your X kill count is: N" chat
    // message (only sent for a handful of tracked bosses/minigames), this
    // fires for essentially every NPC kill — regular monsters like Goblins
    // included — since it's driven by the client script that feeds the
    // native loot tracker, not chat text. See the KILL_COUNT branch in
    // ChatEventDetector for why the chat message is deliberately skipped for
    // "kill"-type counts now: firing both here and there for the same kill
    // would double-count it.
    @Subscribe
    public void onServerNpcLoot(ServerNpcLoot event) {
        String npcName = Text.removeTags(event.getComposition().getName());
        if (npcName == null || npcName.isEmpty() || "null".equals(npcName)) {
            return;
        }
        dispatch(new DetectedEvent("KILL_COUNT", npcName, 1, npcName + " kill (loot-tracker signal)"));
    }

    /** Shared by both detection sources: find matching tiles, report each on a background thread. */
    private void dispatch(DetectedEvent detected) {
        if (!joined || currentState == null) {
            return;
        }
        List<TileState> matches = TileMatcher.findMatches(currentState.tiles, detected.metric, detected.source);
        for (TileState tile : matches) {
            new Thread(() -> reportCompletion(tile, detected), "bingo-report").start();
        }
    }

    private void reportCompletion(TileState tile, DetectedEvent detected) {
        try {
            CompletionResponse response = apiClient.reportCompletion(
                    tile.id, detected.metric, detected.source, detected.amount, detected.rawEvidence);
            // justCompleted is only true on the exact report that pushed this
            // tile from incomplete -> completed — that's what triggers the
            // pop-up, not every accepted report (which would fire on every
            // single kill/drop toward a multi-step tile).
            if (response != null && response.accepted && response.justCompleted) {
                completionOverlay.queueCompletion(tile.title, tile.points);
                playCompletionSound();
            }
            // Re-fetch so the panel and progress overlay reflect the new
            // state immediately for the player who triggered it. Teammates
            // pick this up within POLL_INTERVAL_SECONDS via the background
            // poll started in startUp() rather than an instant push.
            refreshBoard();
        } catch (Exception e) {
            SwingUtilities.invokeLater(() -> panel.showError(e.getMessage()));
        }
    }

    private void playCompletionSound() {
        try {
            audioPlayer.play(BingoPlugin.class, COMPLETION_SOUND_RESOURCE, 0f);
        } catch (Exception e) {
            // Non-critical — a missing/corrupt sound file shouldn't break
            // completion reporting or the pop-up.
            log.warn("Failed to play tile completion sound", e);
        }
    }

    // Toolbar icon: a small light-blue 3x3 bingo grid, drawn in code rather
    // than a bundled image resource so there's no separate asset to keep in
    // sync — swap for a real icon.png before publishing if a hand-drawn one
    // is ever wanted instead.
    private static BufferedImage createBingoIcon() {
        int cells = 3;
        int gap = 1;
        int cellSize = 5;
        int size = gap + cells * (cellSize + gap);

        BufferedImage icon = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = icon.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(100, 200, 255));
        for (int row = 0; row < cells; row++) {
            for (int col = 0; col < cells; col++) {
                int x = gap + col * (cellSize + gap);
                int y = gap + row * (cellSize + gap);
                g.fillRoundRect(x, y, cellSize, cellSize, 1, 1);
            }
        }
        g.dispose();
        return icon;
    }
}

package com.misclickers.bingo;

import com.misclickers.bingo.api.dto.BoardStateResponse;
import com.misclickers.bingo.api.dto.TileState;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;

/**
 * Side-of-screen list of every tile the team has unfinished, nonzero
 * progress on, e.g. "Cut sapphire: 6/10". Complements the sidebar panel
 * (which shows the whole board) by surfacing live progress without needing
 * that panel open. A standard RuneLite OverlayPanel — draggable and
 * resizable by the player, position/size persisted like any other overlay.
 */
public class BingoProgressOverlay extends OverlayPanel {
    private static final int MAX_TITLE_CHARS = 22;

    private final BingoPlugin plugin;
    private final BingoConfig config;

    @Inject
    private BingoProgressOverlay(BingoPlugin plugin, BingoConfig config) {
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        panelComponent.setPreferredSize(new Dimension(200, 0));
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.showProgressOverlay()) {
            return null;
        }

        panelComponent.getChildren().clear();

        BoardStateResponse state = plugin.getCurrentState();
        if (state == null) {
            return null;
        }

        boolean any = false;
        for (TileState tile : state.tiles) {
            if (tile.completed) {
                continue;
            }
            String progress = TileProgressFormatter.format(tile);
            if (progress.startsWith("0/")) {
                continue; // no progress yet on this tile — nothing worth showing
            }
            if (!any) {
                panelComponent.getChildren().add(TitleComponent.builder()
                        .text("Bingo Progress")
                        .color(Color.ORANGE)
                        .build());
                any = true;
            }
            panelComponent.getChildren().add(LineComponent.builder()
                    .left(truncate(tile.title))
                    .right(progress)
                    .build());
        }

        if (!any) {
            return null;
        }
        return super.render(graphics);
    }

    private static String truncate(String title) {
        return title.length() > MAX_TITLE_CHARS ? title.substring(0, MAX_TITLE_CHARS - 1) + "…" : title;
    }
}

package com.misclickers.bingo;

import com.misclickers.bingo.api.dto.BoardStateResponse;
import com.misclickers.bingo.api.dto.TileState;
import net.runelite.client.game.ItemManager;

import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.LayoutManager;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;

/**
 * Builds the tile-grid Swing tree for a BoardStateResponse. Extracted out of
 * BingoPanel so both the "my board" panel and the leaderboard's spectate
 * view can share one implementation — this class is stateless, it just
 * populates whatever gridPanel it's handed.
 */
final class BoardGridRenderer {
    private static final int GRID_HORIZONTAL_MARGIN = 14;
    private static final int TILE_CORNER_RADIUS = 8;

    // Same colors BingoPanel used inline before — kept here now that this is
    // the only place that paints tile cells.
    private static final Color TILE_INCOMPLETE_COLOR = new Color(24, 24, 24);
    private static final Color TILE_COMPLETE_COLOR = new Color(32, 63, 33);

    private BoardGridRenderer() {}

    /**
     * Clears gridPanel and rebuilds it from state. panelWidth is the
     * caller's own PANEL_WIDTH (PluginPanel.PANEL_WIDTH), passed in rather
     * than read from a constant here since this class isn't itself a panel.
     */
    static void render(JPanel gridPanel, BoardStateResponse state, ItemManager itemManager, int panelWidth) {
        gridPanel.removeAll();
        gridPanel.setLayout(new GridLayout(state.board.rows, state.board.cols, 2, 2));

        int usableWidth = panelWidth - GRID_HORIZONTAL_MARGIN;
        int cellSize = Math.max(24, usableWidth / Math.max(1, state.board.cols));

        // Tiles come back from the API already ordered by row then column.
        for (TileState tile : state.tiles) {
            gridPanel.add(buildCell(tile, itemManager, cellSize));
        }

        gridPanel.revalidate();
        gridPanel.repaint();
    }

    private static JPanel buildCell(TileState tile, ItemManager itemManager, int cellSize) {
        RoundedPanel cell = new RoundedPanel(new BorderLayout(), TILE_CORNER_RADIUS);
        cell.setPreferredSize(new Dimension(cellSize, cellSize));
        cell.setBackground(tile.completed ? TILE_COMPLETE_COLOR : TILE_INCOMPLETE_COLOR);
        // A little breathing room on every side so the icon/title isn't
        // flush against the rounded corners and the progress row isn't
        // glued to the very bottom edge.
        cell.setBorder(new EmptyBorder(4, 3, 3, 3));

        String progressText = TileProgressFormatter.format(tile);
        // Tooltip stays title + progress regardless of whether the tile
        // shows an icon or text — the icon replaces the title label
        // visually, but doesn't change what identifies the tile on hover.
        cell.setToolTipText(tile.title + " (" + tile.points + " pts) — " + progressText);

        if (tile.iconItemId != null) {
            // itemManager.getImage() returns an AsyncBufferedImage that
            // starts blank and fills in once the client renders the real
            // sprite — addTo() wires up the repaint-on-load callback so the
            // label doesn't need any manual refresh logic here.
            // BorderLayout.CENTER stretches this label to fill all leftover
            // space above the SOUTH progress row, and the label's own
            // horizontal/vertical alignment centers the icon within that
            // space. Note OSRS item sprites aren't always visually centered
            // within their own canvas (some reserve padding for a
            // stack-count number in a corner), so a slightly off-center look
            // for certain items is the sprite itself, not this layout.
            JLabel iconLabel = new JLabel();
            iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
            iconLabel.setVerticalAlignment(SwingConstants.CENTER);
            itemManager.getImage(tile.iconItemId).addTo(iconLabel);
            cell.add(iconLabel, BorderLayout.CENTER);
        } else {
            // width:Npx forces Swing's HTML renderer to word-wrap the title
            // instead of overflowing past the cell edge; text-align:center
            // centers each wrapped line rather than leaving them ragged-left.
            int labelWidth = Math.max(20, cellSize - 8);
            JLabel titleLabel = new JLabel("<html><body style='width:" + labelWidth
                    + "px; text-align:center'>" + tile.title + "</body></html>");
            titleLabel.setForeground(Color.WHITE);
            titleLabel.setFont(titleLabel.getFont().deriveFont(10f));
            titleLabel.setHorizontalAlignment(SwingConstants.CENTER);
            titleLabel.setVerticalAlignment(SwingConstants.CENTER);
            cell.add(titleLabel, BorderLayout.CENTER);
        }

        JLabel progressLabel = new JLabel(progressText);
        progressLabel.setForeground(new Color(200, 200, 200));
        // Bumped up from 9f now that icon tiles don't also need room for
        // wrapped title text above it — 12f reads much better and still has
        // shrinkFontToFit below as a safety net on narrow cells.
        progressLabel.setFont(progressLabel.getFont().deriveFont(12f));
        progressLabel.setHorizontalAlignment(SwingConstants.CENTER);
        // Shrinks the font until "10/10"-style text actually fits the cell
        // width instead of getting clipped at the right edge — small cells
        // (wide boards) otherwise had no fallback once the label's natural
        // text width exceeded the cell width.
        shrinkFontToFit(progressLabel, Math.max(14, cellSize - 6));
        cell.add(progressLabel, BorderLayout.SOUTH);

        return cell;
    }

    /** Reduces label's font size (down to a 7pt floor) until its current text fits maxWidth. */
    private static void shrinkFontToFit(JLabel label, int maxWidth) {
        Font font = label.getFont();
        FontMetrics metrics = label.getFontMetrics(font);
        while (font.getSize() > 7 && metrics.stringWidth(label.getText()) > maxWidth) {
            font = font.deriveFont((float) font.getSize() - 1f);
            metrics = label.getFontMetrics(font);
        }
        label.setFont(font);
    }

    /**
     * A JPanel that paints its background as a rounded rectangle instead of
     * a hard-edged square. Swing has no built-in support for rounded-corner
     * panels short of custom painting, so this fills the shape itself in
     * paintComponent and relies on setOpaque(false) to stop the normal
     * square background fill from painting underneath/around it.
     */
    static final class RoundedPanel extends JPanel {
        private final int cornerRadius;

        RoundedPanel(LayoutManager layout, int cornerRadius) {
            super(layout);
            this.cornerRadius = cornerRadius;
            setOpaque(false);
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(getBackground());
            g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), cornerRadius, cornerRadius));
            g2.dispose();
            super.paintComponent(g);
        }
    }
}

package com.misclickers.bingo;

import java.util.regex.Matcher;

/**
 * Runs a chat message against every known pattern and returns the first
 * match as a normalized (metric, source) event, or null if nothing matched.
 * Pure function, no RuneLite dependencies — easy to reason about in
 * isolation from the plugin wiring.
 */
public final class ChatEventDetector {
    private ChatEventDetector() {
    }

    public static final class DetectedEvent {
        public final String metric;
        public final String source;
        public final int amount;
        public final String rawEvidence;

        DetectedEvent(String metric, String source, int amount, String rawEvidence) {
            this.metric = metric;
            this.source = source;
            this.amount = amount;
            this.rawEvidence = rawEvidence;
        }
    }

    public static DetectedEvent detect(String message) {
        Matcher killCount = ChatPatterns.KILL_COUNT.matcher(message);
        if (killCount.find()) {
            String countType = killCount.group(2);
            // "kill"-type counts are now detected via
            // BingoPlugin.onServerNpcLoot() instead — that fires for every
            // NPC kill (goblins included), not just the handful of
            // bosses/minigames that happen to print this chat message.
            // Falling through here for "kill" avoids double-counting the
            // same death from both sources. harvest/lap/completion/success/
            // Total Ticket counts have no other signal, so they still go
            // through chat.
            if (!"kill".equalsIgnoreCase(countType)) {
                String subject = killCount.group(1).trim();
                return new DetectedEvent("KILL_COUNT", subject, 1, message);
            }
        }

        // Item drops are detected via NpcLootReceived instead (real
        // quantities, fires on every kill) — see BingoPlugin and the note on
        // ChatPatterns.COLLECTION_LOG_ITEM for why chat detection isn't used
        // for this metric.

        Matcher hunterRumour = ChatPatterns.HUNTER_RUMOUR.matcher(message);
        if (hunterRumour.find()) {
            return new DetectedEvent("ACTIVITY_COMPLETION", "Hunter rumour completion", 1, message);
        }

        Matcher pet = ChatPatterns.PET_RECEIVED.matcher(message);
        if (pet.find()) {
            return new DetectedEvent("ACTIVITY_COMPLETION", "Pet received", 1, message);
        }

        Matcher raid = ChatPatterns.RAID_COMPLETE.matcher(message);
        if (raid.find()) {
            // Can't tell which raid from this message alone — the board's
            // "Complete 50 Raids" tile is set up to accept this one generic
            // label rather than per-raid labels, see fixtures/*.json.
            return new DetectedEvent("ACTIVITY_COMPLETION", "raid completion", 1, message);
        }

        Matcher lms = ChatPatterns.LMS_WIN.matcher(message);
        if (lms.find()) {
            return new DetectedEvent("ACTIVITY_COMPLETION", "Last Man Standing win", 1, message);
        }

        Matcher clue = ChatPatterns.CLUE_COMPLETE.matcher(message);
        if (clue.find()) {
            String tier = clue.group(1).toLowerCase();
            String tierLabel = Character.toUpperCase(tier.charAt(0)) + tier.substring(1);
            return new DetectedEvent("ACTIVITY_COMPLETION", tierLabel + " clue casket", 1, message);
        }

        // Larran's chest (Dagon'hai piece source) isn't handled here — unlike
        // every other pattern in this class, matching the "chest opened"
        // message alone doesn't tell us what was obtained. That requires
        // snapshotting inventory state and diffing against the next
        // inventory-changed event, which needs RuneLite's Client/ItemManager
        // and so lives in BingoPlugin.onChatMessage/onItemContainerChanged
        // instead of this pure-function detector.

        Matcher sapphire = ChatPatterns.CUT_SAPPHIRE.matcher(message);
        if (sapphire.find()) {
            return new DetectedEvent("ACTIVITY_COMPLETION", "Cut sapphire", 1, message);
        }

        Matcher buryBones = ChatPatterns.BONES_BURIED.matcher(message);
        if (buryBones.find()) {
            String boneType = buryBones.group(1).trim().toLowerCase();
            return new DetectedEvent("ACTIVITY_COMPLETION", "Bury " + boneType, 1, message);
        }

        Matcher mahoganyHomes = ChatPatterns.MAHOGANY_HOMES_CONTRACT.matcher(message);
        if (mahoganyHomes.find()) {
            return new DetectedEvent("ACTIVITY_COMPLETION", "Mahogany Homes contract completion", 1, message);
        }

        // Synthetic source label ("Clue reward value"), not the literal
        // item name "Coins" — keeps this isolated from any unrelated coin
        // pickup elsewhere (e.g. a monster drop), so a tile tracking total
        // clue value only ever accumulates from actual clue rewards.
        Matcher clueValue = ChatPatterns.CLUE_VALUE.matcher(message);
        if (clueValue.find()) {
            int coins = Integer.parseInt(clueValue.group(1).replace(",", ""));
            return new DetectedEvent("ITEM_OBTAINED", "Clue reward value", coins, message);
        }

        return null;
    }
}

package com.misclickers.bingo;

import java.util.regex.Pattern;

/**
 * Chat message regexes used to detect tile-completing events. Where noted,
 * these are copied directly from RuneLite's own official ChatCommandsPlugin
 * source (runelite-client/.../chatcommands/ChatCommandsPlugin.java) — high
 * confidence they're exactly right, since that's the same code the KC/CA
 * hiscore tracking in the live client uses. The rest are best-effort based
 * on well-known message text and should be double-checked in-game before
 * relying on them for anything that matters.
 */
public final class ChatPatterns {
    private ChatPatterns() {
    }

    // Verified against RuneLite source. Matches the "Your X kill count is: N"
    // family of messages: kill/harvest/lap/completion/success/Total Ticket
    // counts. Group 2 (added) is which of those words matched, so
    // ChatEventDetector can tell "kill" apart from the rest — combat kills
    // are now detected via BingoPlugin.onServerNpcLoot() instead (reliable
    // for every NPC, not just the handful with a native kill-count message),
    // so this pattern only drives the non-combat count types now. Kept
    // matching "kill" too (rather than dropping it from the alternation) so
    // this stays a complete, accurate description of the real message
    // format even though that branch is intentionally unused.
    public static final Pattern KILL_COUNT = Pattern.compile(
            "Your (?:completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?(.+?)(?:</col>)?"
                    + " (?:(kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?is:"
                    + " ?<col=[0-9a-f]{6}>([0-9,]+)</col>"
    );

    // Verified against user's own in-game testing: burying bones is actually
    // two separate chat lines — "You dig a hole in the ground." then, as its
    // own message, "You bury the bones." Only the second line carries the
    // bone type, so that's the one matched here; the "dig a hole" line is
    // generic (doesn't even mention bones) and ignored. Group 1 captures the
    // bone type (e.g. "bones", "big bones") so other bone tiers work too
    // without needing their own pattern.
    public static final Pattern BONES_BURIED = Pattern.compile(
            "You bury the (.+)\\.",
            Pattern.CASE_INSENSITIVE
    );

    // Verified against RuneLite source, but NOT currently wired up for
    // ITEM_OBTAINED detection — see BingoPlugin.onNpcLootReceived(). This
    // message only fires the first time you ever get a given item, so it
    // can't track tiles needing more than one (obtain 3 cudgels, obtain 5000
    // Pieces of Eight), and firing it alongside loot-based detection would
    // double-count the very first drop of everything. Kept here since it's
    // still the only detectable signal for non-NPC-kill sources (raid reward
    // chests, minigame rewards) — not yet wired up, see backend-data-model.md
    // follow-ups.
    public static final Pattern COLLECTION_LOG_ITEM = Pattern.compile(
            "New item added to your collection log: (.*)"
    );

    // Verified against RuneLite source. No boss/item name to capture — every
    // match is worth exactly one point of progress toward the rumour tile.
    public static final Pattern HUNTER_RUMOUR = Pattern.compile(
            "You have completed <col=[0-9a-f]{6}>([0-9,]+)</col> rumours? for the Hunter Guild\\."
    );

    // Verified against the OSRS Wiki's Pet page. Three variants: first-time
    // pet with no follower out, first-time pet while already following
    // another pet (goes to inventory instead), and a duplicate roll of a
    // pet already owned (pets are tertiary drops, so these keep rolling
    // even after you already have one). All three should count toward a
    // repeatable "obtain any pet" tile — a dupe roll is still a real pet
    // achievement, the player just already has that one.
    public static final Pattern PET_RECEIVED = Pattern.compile(
            "You have a funny feeling like you're being followed"
                    + "|You feel something weird sneaking into your backpack"
                    + "|You have a funny feeling like you would have been followed"
    );

    // Verified against RuneLite source (embedded in their raid personal-best
    // patterns) — this substring reliably means a raid was just completed,
    // but doesn't tell us which of CoX/ToB/ToA. See BingoPlugin's note on
    // the "raid completion" source label.
    public static final Pattern RAID_COMPLETE = Pattern.compile(
            "Congratulations - your raid is complete!"
    );

    // Confirmed exact text directly from in-game testing. Deliberately easy
    // to trigger repeatedly (a few seconds at a gem rock) — good for
    // validating the whole detection -> report -> panel-update pipeline
    // without needing a boss kill or rare drop.
    public static final Pattern CUT_SAPPHIRE = Pattern.compile("You cut the sapphire\\.");

    // Verified against RuneLite's own LootTrackerPlugin source
    // (CLUE_SCROLL_PATTERN). Group 1 is the tier (e.g. "medium"), lowercase.
    public static final Pattern CLUE_COMPLETE = Pattern.compile(
            "You have completed [0-9]+ ([a-z]+) Treasure Trails?\\.",
            Pattern.CASE_INSENSITIVE
    );

    // Verified against RuneLite's own LootTrackerPlugin source
    // (LARRAN_LOOTED_PATTERN). Fires the instant the chest is opened, before
    // the loot lands in the inventory — used purely as a trigger to snapshot
    // inventory contents just ahead of the drop; see BingoPlugin's
    // onChatMessage/onItemContainerChanged for the diffing logic, since
    // chests (unlike NPC kills) don't fire a dedicated loot event.
    public static final Pattern LARRAN_CHEST_OPENED = Pattern.compile(
            "You have opened Larran's (big|small) chest .*"
    );

    // NOT VERIFIED — placeholder based on general knowledge, not source or
    // search-confirmed exact text. Don't rely on this until confirmed
    // in-game; likely candidate for the next round of fixes.
    public static final Pattern LMS_WIN = Pattern.compile(
            "Congratulations, you have won the game!"
    );

    // Confirmed exact text directly from in-game testing (user completed a
    // contract and reported the live chat line). Reports the player's
    // lifetime running total each time, same shape as the boss "kill count
    // is: N" messages — like those, only used as a one-completion-happened
    // trigger (see ChatEventDetector), not to read the absolute total.
    // Both numbers render in red in-game, i.e. wrapped in a <col=xxxxxx> tag
    // same as KILL_COUNT/HUNTER_RUMOUR above — missed on the first pass,
    // which meant the plain [0-9,]+ version never matched the real message
    // at all (the tag sits directly between "completed"/"of" and the
    // digits, breaking the literal match).
    public static final Pattern MAHOGANY_HOMES_CONTRACT = Pattern.compile(
            "You have completed (?:<col=[0-9a-f]{6}>)?[0-9,]+(?:</col>)? contracts? with a total of"
                    + " (?:<col=[0-9a-f]{6}>)?[0-9,]+(?:</col>)? points\\.",
            Pattern.CASE_INSENSITIVE
    );

    // Confirmed exact wording from in-game testing: "Your treasure is worth
    // around XXX coins!", entirely in red. Since "entirely in red" could
    // mean either the whole line is wrapped in one <col> tag, or just the
    // number is (the two different styles already seen between
    // MAHOGANY_HOMES_CONTRACT and the rest of this file), this allows for
    // either: an optional tag wrapping the whole match, and independently
    // an optional tag wrapping just the number — whichever is actually
    // true, this matches. Group 1 is the coin value, with commas intact
    // (stripped in ChatEventDetector).
    public static final Pattern CLUE_VALUE = Pattern.compile(
            "(?:<col=[0-9a-f]{6}>)?Your treasure is worth around (?:<col=[0-9a-f]{6}>)?([0-9,]+)(?:</col>)? coins!(?:</col>)?",
            Pattern.CASE_INSENSITIVE
    );

    // Confirmed exact text directly from in-game testing (user reported the
    // live clan-chat drop broadcast line). Arrives as ChatMessageType
    // CLAN_MESSAGE/CLAN_GUEST_MESSAGE — a system message in the clan chat,
    // not a player-typed one — so BingoPlugin's type filter has to include
    // those. This is the only detectable signal for items that never come
    // from an NPC kill (minigame/Thieving/skilling rewards like Pharaoh's
    // sceptre from Pyramid Plunder) — but since the broadcast is visible to
    // every clan member, not just whoever got the drop, BingoPlugin must
    // check the captured name against the local player before dispatching,
    // or every online teammate would double-report the same drop. Also
    // depends on the clan's own broadcast settings being on and its rarity/
    // value threshold being low enough to actually announce the item.
    public static final Pattern CLAN_DROP_BROADCAST = Pattern.compile(
            "(.+?) received a (?:rare )?drop: (.+?)(?:\\s*\\([0-9,]+ coins\\))?$"
    );
}

package com.misclickers.bingo;

import com.misclickers.bingo.api.dto.BoardStateResponse;
import com.misclickers.bingo.api.dto.TeamsListResponse;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.FlowLayout;
import java.util.List;
import java.util.function.Consumer;

/**
 * Read-only "spectate another team's board" view. Sits alongside BingoPanel
 * as a second tab (see BingoPlugin) — same grid rendering via
 * BoardGridRenderer, but no refresh-triggers-report plumbing, since this is
 * never the local player's own progress.
 */
public class LeaderboardPanel extends JPanel {
    private final JComboBox<TeamOption> teamSelector = new JComboBox<>();
    private final JLabel statusLabel = new JLabel("Pick a team");
    private final JLabel scoreLabel = new JLabel(" ");
    private final JPanel gridPanel = new JPanel();
    // Same FlowLayout-wrapper trick BingoPanel uses — keeps the grid square
    // instead of letting it stretch to fill the tab's height.
    private final JPanel gridWrapper = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));

    private final ItemManager itemManager;
    private Consumer<String> onTeamSelected;
    // Guards against the selection listener firing (and re-fetching) while
    // setTeams() is repopulating the combo box itself.
    private boolean populatingTeams;

    public LeaderboardPanel(ItemManager itemManager) {
        this.itemManager = itemManager;
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        header.setBorder(new CompoundBorder(
                new MatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
                new EmptyBorder(10, 10, 10, 10)));

        statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        statusLabel.setFont(FontManager.getRunescapeSmallFont());
        scoreLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        scoreLabel.setFont(FontManager.getRunescapeSmallFont());

        teamSelector.setAlignmentX(Component.LEFT_ALIGNMENT);
        teamSelector.setMaximumSize(new java.awt.Dimension(Integer.MAX_VALUE, teamSelector.getPreferredSize().height));
        teamSelector.addActionListener(e -> {
            if (populatingTeams) {
                return;
            }
            TeamOption selected = (TeamOption) teamSelector.getSelectedItem();
            if (selected != null && onTeamSelected != null) {
                onTeamSelected.accept(selected.teamId);
            }
        });

        statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        scoreLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

        header.add(teamSelector);
        header.add(Box.createVerticalStrut(6));
        header.add(statusLabel);
        header.add(scoreLabel);
        add(header, BorderLayout.NORTH);

        gridPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        gridWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
        gridWrapper.add(gridPanel);
        add(gridWrapper, BorderLayout.CENTER);
    }

    /** Called once the teams list has been fetched. Fires onTeamSelected for whichever entry ends up selected. */
    public void setTeams(List<TeamsListResponse.TeamSummary> teams) {
        populatingTeams = true;
        Object previouslySelected = teamSelector.getSelectedItem();
        String previousTeamId = previouslySelected instanceof TeamOption ? ((TeamOption) previouslySelected).teamId : null;

        teamSelector.removeAllItems();
        for (TeamsListResponse.TeamSummary team : teams) {
            teamSelector.addItem(new TeamOption(team.id, team.name));
        }

        // Keep the same team selected across a refresh if it's still on the
        // board; otherwise fall back to whatever the combo box defaults to
        // (its first entry). Stays under populatingTeams so none of this
        // triggers the action listener — the explicit call below is the
        // single source of truth for firing onTeamSelected, since
        // setSelectedIndex() is a silent no-op whenever the index it's
        // given is already the current selection (notably true for the
        // very first population, where addItem already auto-selected
        // index 0).
        boolean restored = false;
        if (previousTeamId != null) {
            for (int i = 0; i < teamSelector.getItemCount(); i++) {
                if (teamSelector.getItemAt(i).teamId.equals(previousTeamId)) {
                    teamSelector.setSelectedIndex(i);
                    restored = true;
                    break;
                }
            }
        }
        if (!restored && teamSelector.getItemCount() > 0) {
            teamSelector.setSelectedIndex(0);
        }
        populatingTeams = false;

        TeamOption selected = (TeamOption) teamSelector.getSelectedItem();
        if (selected != null && onTeamSelected != null) {
            onTeamSelected.accept(selected.teamId);
        }
    }

    public void setOnTeamSelected(Consumer<String> onTeamSelected) {
        this.onTeamSelected = onTeamSelected;
    }

    public void showError(String message) {
        statusLabel.setText("Error: " + message);
    }

    public void render(BoardStateResponse state) {
        statusLabel.setText(state.board.name);
        scoreLabel.setText("Score: " + state.score.total
                + " (" + state.score.completedCount + "/" + state.tiles.size() + " tiles)");

        BoardGridRenderer.render(gridPanel, state, itemManager, net.runelite.client.ui.PluginPanel.PANEL_WIDTH);

        gridWrapper.revalidate();
        gridWrapper.repaint();
        revalidate();
        repaint();
    }

    private static final class TeamOption {
        final String teamId;
        final String teamName;

        TeamOption(String teamId, String teamName) {
            this.teamId = teamId;
            this.teamName = teamName;
        }

        @Override
        public String toString() {
            return teamName;
        }
    }
}

package com.misclickers.bingo;

import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;

/**
 * Fades a small banner onto the top-center of the screen when a tile is
 * completed, styled after OSRS's own "New item added to your collection
 * log" pop-up — dark semi-transparent box, gold/bronze border, orange
 * header line, RuneScape UI font. Not a pixel-perfect recreation (the
 * game's actual sprite assets aren't available to a plugin), but matches
 * the silhouette and colour palette closely.
 *
 * queueCompletion() is safe to call from any thread (completions are
 * reported from background "bingo-report" threads); the queue is drained on
 * the client thread inside render(), one announcement at a time.
 */
public class TileCompletionOverlay extends Overlay {
    private static final int FADE_IN_MS = 250;
    private static final int HOLD_MS = 3000;
    private static final int FADE_OUT_MS = 500;
    private static final int TOTAL_MS = FADE_IN_MS + HOLD_MS + FADE_OUT_MS;

    private static final Color BACKGROUND = new Color(0, 0, 0, 215);
    private static final Color BORDER = new Color(178, 140, 62); // OSRS interface gold/bronze
    private static final Color HEADER = new Color(255, 152, 31); // OSRS orange
    private static final Color POINTS_COLOR = new Color(255, 255, 0);
    private static final Color TITLE_COLOR = Color.WHITE;

    private final Font headerFont = FontManager.getRunescapeBoldFont();
    private final Font bodyFont = FontManager.getRunescapeFont();

    private final Queue<Announcement> queue = new ConcurrentLinkedQueue<>();
    private Announcement current;
    private long shownAtMillis;

    @Inject
    private TileCompletionOverlay() {
        setPosition(OverlayPosition.TOP_CENTER);
    }

    public void queueCompletion(String tileTitle, int points) {
        queue.add(new Announcement(tileTitle, points));
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (current == null) {
            current = queue.poll();
            if (current == null) {
                return null;
            }
            shownAtMillis = System.currentTimeMillis();
        }

        long elapsed = System.currentTimeMillis() - shownAtMillis;
        if (elapsed >= TOTAL_MS) {
            current = null;
            return null;
        }

        float alpha;
        if (elapsed < FADE_IN_MS) {
            alpha = elapsed / (float) FADE_IN_MS;
        } else if (elapsed < FADE_IN_MS + HOLD_MS) {
            alpha = 1f;
        } else {
            alpha = 1f - (elapsed - FADE_IN_MS - HOLD_MS) / (float) FADE_OUT_MS;
        }
        alpha = Math.max(0f, Math.min(1f, alpha));

        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        FontMetrics headerMetrics = graphics.getFontMetrics(headerFont);
        FontMetrics bodyMetrics = graphics.getFontMetrics(bodyFont);

        String headerText = "Bingo tile completed!";
        String titleText = current.title;
        String pointsText = "+" + current.points + (current.points == 1 ? " pt" : " pts");

        int contentWidth = Math.max(headerMetrics.stringWidth(headerText),
                Math.max(bodyMetrics.stringWidth(titleText), bodyMetrics.stringWidth(pointsText)));
        int width = contentWidth + 32;
        int height = headerMetrics.getHeight() + bodyMetrics.getHeight() * 2 + 20;

        Composite originalComposite = graphics.getComposite();
        graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));

        graphics.setColor(BACKGROUND);
        graphics.fill(new RoundRectangle2D.Float(0, 0, width, height, 10, 10));
        graphics.setColor(BORDER);
        graphics.setStroke(new BasicStroke(2f));
        graphics.draw(new RoundRectangle2D.Float(1, 1, width - 2, height - 2, 10, 10));

        int y = 6 + headerMetrics.getAscent();
        graphics.setFont(headerFont);
        graphics.setColor(HEADER);
        drawCentered(graphics, headerText, width, y, headerMetrics);

        y += bodyMetrics.getHeight() + 2;
        graphics.setFont(bodyFont);
        graphics.setColor(TITLE_COLOR);
        drawCentered(graphics, titleText, width, y, bodyMetrics);

        y += bodyMetrics.getHeight();
        graphics.setColor(POINTS_COLOR);
        drawCentered(graphics, pointsText, width, y, bodyMetrics);

        graphics.setComposite(originalComposite);

        return new Dimension(width, height);
    }

    private static void drawCentered(Graphics2D graphics, String text, int width, int baselineY, FontMetrics metrics) {
        int x = (width - metrics.stringWidth(text)) / 2;
        graphics.drawString(text, x, baselineY);
    }

    private static final class Announcement {
        final String title;
        final int points;

        Announcement(String title, int points) {
            this.title = title;
            this.points = points;
        }
    }
}

package com.misclickers.bingo;

import com.misclickers.bingo.api.dto.Condition;
import com.misclickers.bingo.api.dto.TileGroup;
import com.misclickers.bingo.api.dto.TileState;

import java.util.ArrayList;
import java.util.List;

/**
 * Given the currently cached board tiles and a detected (metric, source)
 * event, finds which tiles it's relevant to. This mirrors the matching rule
 * the backend applies in src/lib/completionLogic.ts — it's a client-side
 * pre-filter so we don't spam the API with obviously irrelevant events, not
 * the authority on whether a completion actually counts (the server always
 * re-checks and is free to reject).
 */
public final class TileMatcher {
    private TileMatcher() {
    }

    public static List<TileState> findMatches(List<TileState> tiles, String metric, String source) {
        List<TileState> matches = new ArrayList<>();
        if (tiles == null) {
            return matches;
        }
        for (TileState tile : tiles) {
            if (!metric.equals(tile.metric)) {
                continue;
            }
            // Once a non-repeatable tile is done, nothing more to report.
            // Repeatable tiles (e.g. the pet tile) keep accepting events for
            // bonus credit even after their first completion.
            if (tile.completed && !tile.repeatable) {
                continue;
            }
            // SUM/EACH tiles keep their match criteria in the flat
            // `sources` list. AND_OR and OR_AND tiles instead nest it inside
            // `groups`/`sets` — each a list of {source, target} conditions
            // — and leave `sources` empty/unused (see TileState and the
            // backend schema), so those have to be checked separately or
            // every event for a groups/sets tile gets silently dropped here
            // before it's ever reported.
            if (containsIgnoreCase(tile.sources, source)
                    || anyConditionMatches(tile.groups, source)
                    || anyConditionMatches(tile.sets, source)) {
                matches.add(tile);
            }
        }
        return matches;
    }

    private static boolean containsIgnoreCase(List<String> sources, String source) {
        if (sources == null) {
            return false;
        }
        for (String s : sources) {
            if (s.equalsIgnoreCase(source)) {
                return true;
            }
        }
        return false;
    }

    /** True if any condition in any group/set names this source — used for both AND_OR groups and OR_AND sets. */
    private static boolean anyConditionMatches(List<TileGroup> groupsOrSets, String source) {
        if (groupsOrSets == null) {
            return false;
        }
        for (TileGroup group : groupsOrSets) {
            if (group.conditions == null) {
                continue;
            }
            for (Condition condition : group.conditions) {
                if (condition.source.equalsIgnoreCase(source)) {
                    return true;
                }
            }
        }
        return false;
    }
}

package com.misclickers.bingo;

import com.misclickers.bingo.api.dto.Condition;
import com.misclickers.bingo.api.dto.TileGroup;
import com.misclickers.bingo.api.dto.TileState;

/**
 * Shared "x/y" progress text formatting, used by both the side panel and the
 * on-screen progress overlay so they can never disagree with each other.
 */
public final class TileProgressFormatter {
    private TileProgressFormatter() {
    }

    /**
     * For "each" mode tiles (full-set tiles, e.g. "obtain all 4 axe pieces")
     * this is how many of the required sources have hit their own target so
     * far. For "and_or" mode tiles it's how many of the tile's OR-groups
     * already have a satisfied condition (out of the total group count). For
     * "or_and" mode tiles it's progress toward whichever single AND-set is
     * furthest along (e.g. 2/3 Blood Moon pieces, even if other sets have
     * fewer) — there's no single shared "x out of y" across sets the way
     * AND_OR has across groups, since only one set needs to fully complete.
     * For "sum" mode tiles it's raw progress against the target (e.g. kill
     * count so far / kills needed).
     */
    public static String format(TileState tile) {
        if ("EACH".equals(tile.mode) && tile.sources != null && !tile.sources.isEmpty()) {
            int satisfied = 0;
            for (String source : tile.sources) {
                Integer progress = tile.eachProgress != null ? tile.eachProgress.get(source) : null;
                if (progress != null && progress >= targetFor(tile, source)) {
                    satisfied++;
                }
            }
            return satisfied + "/" + tile.sources.size();
        }
        if ("AND_OR".equals(tile.mode) && tile.groups != null && !tile.groups.isEmpty()) {
            int satisfiedGroups = 0;
            for (TileGroup group : tile.groups) {
                if (groupSatisfied(tile, group)) {
                    satisfiedGroups++;
                }
            }
            return satisfiedGroups + "/" + tile.groups.size();
        }
        if ("OR_AND".equals(tile.mode) && tile.sets != null && !tile.sets.isEmpty()) {
            int bestSatisfied = 0;
            int bestTotal = tile.sets.get(0).conditions == null ? 0 : tile.sets.get(0).conditions.size();
            for (TileGroup set : tile.sets) {
                int total = set.conditions == null ? 0 : set.conditions.size();
                int satisfied = satisfiedCount(tile, set);
                if (satisfied > bestSatisfied || (satisfied == bestSatisfied && total < bestTotal)) {
                    bestSatisfied = satisfied;
                    bestTotal = total;
                }
            }
            return bestSatisfied + "/" + bestTotal;
        }
        return Math.min(tile.sumProgress, tile.target) + "/" + tile.target;
    }

    /** An AND_OR group is satisfied once any one of its own conditions is met. */
    private static boolean groupSatisfied(TileState tile, TileGroup group) {
        if (group.conditions == null) {
            return false;
        }
        for (Condition condition : group.conditions) {
            Integer progress = tile.eachProgress != null ? tile.eachProgress.get(condition.source) : null;
            if (progress != null && progress >= condition.target) {
                return true;
            }
        }
        return false;
    }

    /** How many of a set's own conditions are individually satisfied. */
    private static int satisfiedCount(TileState tile, TileGroup set) {
        if (set.conditions == null) {
            return 0;
        }
        int count = 0;
        for (Condition condition : set.conditions) {
            Integer progress = tile.eachProgress != null ? tile.eachProgress.get(condition.source) : null;
            if (progress != null && progress >= condition.target) {
                count++;
            }
        }
        return count;
    }

    /**
     * The target a given EACH-mode source needs to hit: its own override
     * from tile.sourceTargets if present, otherwise the tile's shared
     * target — mirrors the same fallback the backend applies in
     * completionLogic.ts, so display never disagrees with what actually
     * completes the tile.
     */
    private static int targetFor(TileState tile, String source) {
        if (tile.sourceTargets != null && tile.sourceTargets.containsKey(source)) {
            return tile.sourceTargets.get(source);
        }
        return tile.target;
    }
}

package com.misclickers.bingo.api;

import com.google.gson.Gson;
import com.misclickers.bingo.api.dto.BoardStateResponse;
import com.misclickers.bingo.api.dto.CompletionResponse;
import com.misclickers.bingo.api.dto.JoinResponse;
import com.misclickers.bingo.api.dto.TeamsListResponse;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import javax.inject.Inject;
import java.io.IOException;

/**
 * Thin wrapper around the bingo backend's REST API. Every method here does a
 * blocking network call — always invoke from a background thread, never from
 * the RuneLite client thread (that would freeze the game client).
 */
public class BingoApiClient {
    private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

    private final OkHttpClient httpClient;
    private final Gson gson;

    private String baseUrl;
    private String token;

    @Inject
    public BingoApiClient(OkHttpClient httpClient, Gson gson) {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    public void setBaseUrl(String baseUrl) {
        this.baseUrl = baseUrl.endsWith("/") ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
    }

    public String getToken() {
        return token;
    }

    /**
     * Thrown instead of falling through to the generic "HTTP N" IOException
     * whenever the server says 401 — i.e. authenticateTeam rejected the
     * token as missing, malformed, or expired. Callers that want to react
     * by re-joining (see BingoPlugin.refreshBoard()) can catch this
     * specifically rather than parsing error messages.
     */
    private static void throwIfUnauthorized(Response response, String action) throws UnauthorizedException {
        if (response.code() == 401) {
            throw new UnauthorizedException(action + " failed: token rejected (HTTP 401)");
        }
    }

    /** POST /teams/join — exchanges a join code + RSN for a session token. */
    public JoinResponse join(String joinCode, String rsn) throws IOException {
        String body = gson.toJson(new JoinRequestBody(joinCode, rsn));
        Request request = new Request.Builder()
                .url(baseUrl + "/teams/join")
                .post(RequestBody.create(JSON, body))
                .build();

        try (Response response = httpClient.newCall(request).execute()) {
            if (!response.isSuccessful() || response.body() == null) {
                throw new IOException("Join failed: HTTP " + response.code());
            }
            JoinResponse joinResponse = gson.fromJson(response.body().string(), JoinResponse.class);
            this.token = joinResponse.token;
            return joinResponse;
        }
    }

    /** GET /boards/:boardId/state — requires join() to have run first. */
    public BoardStateResponse fetchBoardState(String boardId) throws IOException {
        if (token == null) {
            throw new IllegalStateException("Not joined yet — call join() first");
        }
        Request request = new Request.Builder()
                .url(baseUrl + "/boards/" + boardId + "/state")
                .header("Authorization", "Bearer " + token)
                .get()
                .build();

        try (Response response = httpClient.newCall(request).execute()) {
            throwIfUnauthorized(response, "Fetching board state");
            if (!response.isSuccessful() || response.body() == null) {
                throw new IOException("Fetching board state failed: HTTP " + response.code());
            }
            return gson.fromJson(response.body().string(), BoardStateResponse.class);
        }
    }

    /** GET /boards/:boardId/teams — list of every team on the board, for the leaderboard dropdown. */
    public TeamsListResponse fetchTeams(String boardId) throws IOException {
        if (token == null) {
            throw new IllegalStateException("Not joined yet — call join() first");
        }
        Request request = new Request.Builder()
                .url(baseUrl + "/boards/" + boardId + "/teams")
                .header("Authorization", "Bearer " + token)
                .get()
                .build();

        try (Response response = httpClient.newCall(request).execute()) {
            throwIfUnauthorized(response, "Fetching teams");
            if (!response.isSuccessful() || response.body() == null) {
                throw new IOException("Fetching teams failed: HTTP " + response.code());
            }
            return gson.fromJson(response.body().string(), TeamsListResponse.class);
        }
    }

    /**
     * GET /boards/:boardId/teams/:targetTeamId/state — same shape as
     * fetchBoardState, but for another team on the board. Used by the
     * leaderboard tab's read-only spectate view.
     */
    public BoardStateResponse fetchTeamState(String boardId, String targetTeamId) throws IOException {
        if (token == null) {
            throw new IllegalStateException("Not joined yet — call join() first");
        }
        Request request = new Request.Builder()
                .url(baseUrl + "/boards/" + boardId + "/teams/" + targetTeamId + "/state")
                .header("Authorization", "Bearer " + token)
                .get()
                .build();

        try (Response response = httpClient.newCall(request).execute()) {
            throwIfUnauthorized(response, "Fetching team state");
            if (!response.isSuccessful() || response.body() == null) {
                throw new IOException("Fetching team state failed: HTTP " + response.code());
            }
            return gson.fromJson(response.body().string(), BoardStateResponse.class);
        }
    }

    /**
     * POST /completions — reports a detected game event toward a specific
     * tile. The server re-validates it against that tile's criteria
     * independently; this call being accepted doesn't guarantee the tile
     * actually completed (see the response body if you need to know).
     */
    public CompletionResponse reportCompletion(String tileId, String metric, String source, int amount, String rawEvidence) throws IOException {
        if (token == null) {
            throw new IllegalStateException("Not joined yet — call join() first");
        }
        String body = gson.toJson(new CompletionRequestBody(tileId, metric, source, amount, rawEvidence));
        Request request = new Request.Builder()
                .url(baseUrl + "/completions")
                .header("Authorization", "Bearer " + token)
                .post(RequestBody.create(JSON, body))
                .build();

        try (Response response = httpClient.newCall(request).execute()) {
            throwIfUnauthorized(response, "Reporting completion");
            if (!response.isSuccessful() || response.body() == null) {
                throw new IOException("Reporting completion failed: HTTP " + response.code());
            }
            return gson.fromJson(response.body().string(), CompletionResponse.class);
        }
    }

    private static final class JoinRequestBody {
        final String joinCode;
        final String rsn;

        JoinRequestBody(String joinCode, String rsn) {
            this.joinCode = joinCode;
            this.rsn = rsn;
        }
    }

    private static final class CompletionRequestBody {
        final String tileId;
        final String metric;
        final String source;
        final int amount;
        final String rawEvidence;

        CompletionRequestBody(String tileId, String metric, String source, int amount, String rawEvidence) {
            this.tileId = tileId;
            this.metric = metric;
            this.source = source;
            this.amount = amount;
            this.rawEvidence = rawEvidence;
        }
    }
}

package com.misclickers.bingo.api;

import java.io.IOException;

/**
 * Thrown by BingoApiClient instead of a plain IOException when the server
 * responds 401 — i.e. the current token is missing, invalid, or expired.
 * Kept as its own type so callers can specifically react by re-joining
 * (getting a fresh token) rather than just surfacing a generic error, which
 * previously required the player to manually restart the plugin once a
 * long-lived session's token expired. See BingoPlugin.refreshBoard().
 */
public class UnauthorizedException extends IOException {
    public UnauthorizedException(String message) {
        super(message);
    }
}

package com.misclickers.bingo.api.dto;

public class BoardInfo {
    public String id;
    public String name;
    public int rows;
    public int cols;
}

package com.misclickers.bingo.api.dto;

import java.util.List;

/** Response shape from GET /boards/:boardId/state. */
public class BoardStateResponse {
    public BoardInfo board;
    public List<TileState> tiles;
    public ScoreBreakdown score;
}

package com.misclickers.bingo.api.dto;

/**
 * Response body from POST /completions — see backend routes/completions.ts.
 * Only the fields the plugin actually reads are declared here; Gson just
 * ignores the rest of the JSON (score, repeatCredited, reason, etc).
 */
public class CompletionResponse {
    public boolean accepted;
    // True only on the exact report that pushed the tile from
    // incomplete -> completed. Used to trigger the completion pop-up without
    // needing to diff board state ourselves.
    public boolean justCompleted;
}

package com.misclickers.bingo.api.dto;

/**
 * One leaf of an AND_OR tile's group structure: "obtain/kill/complete
 * `source` at least `target` times satisfies this condition." See
 * TileGroup and the backend's completionLogic.ts for the full semantics.
 */
public class Condition {
    public String source;
    public int target;
}

package com.misclickers.bingo.api.dto;

/**
 * Response shape from POST /teams/join — see backend routes/teams.ts.
 * Field names match the JSON keys exactly so Gson can map them with no
 * annotations needed.
 */
public class JoinResponse {
    public String token;
    public String teamId;
    public String teamName;
    public String boardId;
}

package com.misclickers.bingo.api.dto;

/** Mirrors backend src/scoring.ts's ScoreBreakdown return shape exactly. */
public class ScoreBreakdown {
    public int tilePoints;
    public int repeatBonusPoints;
    public int lineBonusPoints;
    public int blackoutBonusPoints;
    public int total;
    public int completedCount;
}

package com.misclickers.bingo.api.dto;

import java.util.List;

/** Response shape from GET /boards/:boardId/teams. */
public class TeamsListResponse {
    public List<TeamSummary> teams;

    public static final class TeamSummary {
        public String id;
        public String name;
    }
}

package com.misclickers.bingo.api.dto;

import java.util.List;

/**
 * One OR-group of an AND_OR tile: satisfied when any one of its conditions
 * has been met. A tile completes once every one of its groups is satisfied
 * — see TileState.groups and the backend's completionLogic.ts.
 */
public class TileGroup {
    public List<Condition> conditions;
}

package com.misclickers.bingo.api.dto;

import java.util.Map;

/**
 * One tile as returned by GET /boards/:boardId/state — see backend
 * routes/boards.ts. eachProgress is only populated for "each" mode tiles.
 */
public class TileState {
    public String id;
    public String title;
    public int points;
    public int row;
    public int col;
    public boolean repeatable;
    public int target;
    // Detection criteria — what game events this tile is watching for.
    public String metric;
    public String mode;
    public java.util.List<String> sources;
    // EACH mode only — per-source override of `target` (e.g. {"Goblin": 2,
    // "Chicken": 3}). Null, or missing a given source, means that source
    // uses `target` instead — see TileProgressFormatter.
    public Map<String, Integer> sourceTargets;
    // AND_OR mode only — list of OR-groups; the tile completes once every
    // group has at least one satisfied condition. See TileProgressFormatter.
    public java.util.List<TileGroup> groups;
    // OR_AND mode only — list of AND-sets; the tile completes once any one
    // set has every one of its own conditions satisfied. Reuses the same
    // TileGroup shape as `groups` (just a list of conditions) since the
    // structure is identical — only the completion rule differs, and that
    // lives in TileProgressFormatter, not the DTO. See Mode.OR_AND.
    public java.util.List<TileGroup> sets;
    // Optional OSRS item ID to render (via ItemManager) instead of the tile's
    // title text — independent of metric/sources, see backend schema.prisma.
    // Gson leaves this null when the field is absent from the JSON response.
    public Integer iconItemId;
    public boolean completed;
    public int repeatCount;
    public int sumProgress;
    public Map<String, Integer> eachProgress;
}

package com.misclickers.bingo;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Not a JUnit test — this is RuneLite's documented pattern for running a
 * plugin standalone during development. Run this class's main() from
 * IntelliJ (right-click -> Run) and it launches the real RuneLite client
 * with this plugin sideloaded, so you can log in and click around it live.
 */
public class BingoPluginTest {
    public static void main(String[] args) throws Exception {
        ExternalPluginManager.loadBuiltin(BingoPlugin.class);
        RuneLite.main(args);
    }
}
